#include <cuda_runtime.h>

#define TILE_SIZE 16
#define UNROLL_FACTOR 4

__global__ void matmul_kernel(const float* __restrict__ A, const float* __restrict__ B, float* __restrict__ C, int N) {
    __shared__ float sA[TILE_SIZE][TILE_SIZE+1];  // +1 to avoid bank conflicts
    __shared__ float sB[TILE_SIZE][TILE_SIZE+1];

    int row = blockIdx.y * TILE_SIZE + threadIdx.y;
    int col = blockIdx.x * TILE_SIZE + threadIdx.x;

    float sum[UNROLL_FACTOR] = {0.0f};
    int num_tiles = (N + TILE_SIZE - 1) / TILE_SIZE;

    for (int tile = 0; tile < num_tiles; tile += UNROLL_FACTOR) {
        // Preload multiple tiles into registers
        float regA[UNROLL_FACTOR], regB[UNROLL_FACTOR];

        // Load UNROLL_FACTOR tiles from A into shared memory
        for (int u = 0; u < UNROLL_FACTOR; u++) {
