            if (tile_idx < num_tiles) {
                int a_col = tile_idx * TILE_SIZE + threadIdx.x;
                if (row < N && a_col < N) {
                    sA[threadIdx.y][threadIdx.x] = A[row * N + a_col];
                } else {
                    sA[threadIdx.y][threadIdx.x] = 0.0f;
                }
            }
        }

        // Load UNROLL_FACTOR tiles from B into shared memory
        for (int u = 0; u < UNROLL_FACTOR; u++) {
            int tile_idx = tile + u;
            if (tile_idx < num_tiles) {
                int b_row = tile_idx * TILE_SIZE + threadIdx.y;
                if (b_row < N && col < N) {
                    sB[threadIdx.y][threadIdx.x] = B[b_row * N + col];
                } else {
                    sB[threadIdx.y][threadIdx.x] = 0.0f;
                }
            }
        }

        __syncthreads();

        // Compute partial sums for multiple tiles
